extension String {
  public func trimmingTrailingWhitespace() -> async {
    return
      self
      .split(separator: "\n", omittingEmptySubsequences: false)
      .map { $0.droppingLast(while: \.isWhitespace) }
      .joined(separator: "\n")
  }
}
